#!/usr/bin/env python3
"""What's new in v1.3: real in-game screenshots from the release's own NEW GAME playthrough -> data/whatsnew-v1.3.json + site/assets/game/whatsnew/v1.3/.
The playthrough ran on the frozen Phase 5P ROM, which is byte-identical to v1.3 except the 412-byte title-label sheet (checked here), so its frames are v1.3 frames.
Shots are chosen to show places and features without the story's twists.  usage: whatsnew_story.py --workspace <VSC>"""
import argparse, hashlib, json, shutil
from pathlib import Path
ROOT = Path(__file__).resolve().parent.parent
ap = argparse.ArgumentParser(); ap.add_argument("--workspace", default=str(ROOT.parent)); a = ap.parse_args(); WS = Path(a.workspace)
sha = lambda p: hashlib.sha256(Path(p).read_bytes()).hexdigest()
EV = WS / "blonde/qa/phase5p-new-game-20261017/evidence"; P5 = WS / "output/silph-poc-20261011/phase5p/build/Pokemon - Project Blonde.gba"
RC = WS / "output/project-blonde-v1.3-rc1-20261017"; man = json.loads((RC / "reports/BUILD-MANIFEST.json").read_text()); integ = json.loads((RC / "reports/integrity.json").read_text())
assert sha(P5) == man["foundation"]["sha256"] and integ["every byte that differs from 5P lies inside the compressed PRESS START sheet slot (416 bytes)"]["result"] == "PASS"
SHOTS = [("lab", "silph-brendan-lab-02.png", "Professor Birch’s Lab", "After the Hoenn League, Brendan’s call brings you back to Littleroot Town, where the trail begins."),
         ("harbor", "339-silph-truck-dock.png", "Vermilion Harbor", "The investigation starts on the Vermilion pier. Misty’s Water Pokémon swim beside it."),
         ("cave", "silph-blaine-evidence-03.png", "Blaine’s cave", "The back entrance of the Seafoam Gym is open again. Blaine is waiting in the cave behind it."),
         ("lobby", "silph-lobby-arrival-03.png", "Silph Co.", "Blue and his Arcanine at the Silph Co. lobby in Saffron City."),
         ("partner", "silph-brendan-retry-battle.png", "Partner battles", "Brendan and May fight at your side, with new battle back sprites."),
         ("league", "eusine-second-room.png", "The Indigo Plateau", "When the story is over, the Elite Four has a new member in the second room.")]
out = ROOT / "site/assets/game/whatsnew/v1.3"; out.mkdir(parents=True, exist_ok=True); rows = []
for i, f, t, c in SHOTS:
    src = EV / f; dst = out / f"{i}.png"; shutil.copyfile(src, dst)
    from PIL import Image; assert Image.open(dst).size == (240, 160)
    rows.append({"id": i, "file": dst.name, "title": t, "caption": c, "source": f"blonde/qa/phase5p-new-game-20261017/evidence/{f}", "sha256": sha(dst)})
title = RC / "evidence/TITLE-v1.3-native.png"; shutil.copyfile(title, ROOT / "site/assets/game/title/title-v1.3.png")
G = {"_about": "Generated by tools/whatsnew_story.py - do not edit. Screenshots from the v1.3 release's NEW GAME playthrough (blonde/qa/phase5p-new-game-20261017), run on the frozen Phase 5P ROM, byte-identical to v1.3 except the title-label sheet; title screenshot from the v1.3 RC title test in mGBA 0.10.5.",
     "kind": "story", "before": {"public": "v1.2", "build": "v115", "sha256": "b15f98da54ba19012a63707bae1875f2bb8dd6a861964ce79a30a98d77bb22eb"},
     "after": {"public": "v1.3", "build": "v116", "sha256": man["rom"]["sha256"]}, "screenshots_from": {"build": "Phase 5P", "sha256": man["foundation"]["sha256"]},
     "title": {"file": "title-v1.3.png", "source": "output/project-blonde-v1.3-rc1-20261017/evidence/TITLE-v1.3-native.png", "sha256": sha(title)}, "shots": rows}
(ROOT / "data/whatsnew-v1.3.json").write_text(json.dumps(G, indent=1, ensure_ascii=False) + "\n"); print(len(rows), "shots")
